SET local check_function_bodies = off;

CREATE TABLE "better_supabase"."access_requests" (
  "id"            uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"     uuid                     NOT NULL,
  "user_id"       uuid                     NOT NULL,
  "role"          text                     NOT NULL,
  "previous_role" text,
  "reason"        text,
  "duration"      interval,
  "approval_id"   uuid,
  "granted_at"    timestamp with time zone,
  "expires_at"    timestamp with time zone,
  "ended_at"      timestamp with time zone,
  "created_at"    timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "access_requests_duration_check" CHECK (((duration IS NULL) OR (duration > '00:00:00'::interval))),
  CONSTRAINT "access_requests_pkey" PRIMARY KEY (id),
  CONSTRAINT "access_requests_reason_check" CHECK (((reason IS NULL) OR (length(reason) <= 2000))),
  CONSTRAINT "access_requests_role_check" CHECK (((length(role) >= 1) AND (length(role) <= 200)))
);

ALTER TABLE "better_supabase"."access_requests"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."application_scorecards" (
  "id"               uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"        uuid                     NOT NULL,
  "application_id"   uuid                     NOT NULL,
  "stage_id"         uuid,
  "reviewer_user_id" uuid                     NOT NULL,
  "rating"           smallint                 NOT NULL,
  "recommendation"   text                     NOT NULL,
  "notes"            text,
  "submitted_at"     timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "application_scorecards_application_id_stage_id_reviewer_use_key" UNIQUE NULLS NOT DISTINCT (application_id, stage_id, reviewer_user_id),
  CONSTRAINT "application_scorecards_pkey" PRIMARY KEY (id),
  CONSTRAINT "application_scorecards_rating_check" CHECK (((rating >= 1) AND (rating <= 4))),
  CONSTRAINT "application_scorecards_recommendation_check" CHECK ((recommendation = ANY (ARRAY['strong_no'::text, 'no'::text, 'yes'::text, 'strong_yes'::text])))
);

ALTER TABLE "better_supabase"."application_scorecards"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."applications" (
  "id"               uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"        uuid                     NOT NULL,
  "job_id"           uuid                     NOT NULL,
  "candidate_type"   text                     NOT NULL,
  "candidate_id"     text                     NOT NULL,
  "source"           text,
  "owner_user_id"    uuid,
  "pipeline_id"      uuid,
  "stage_id"         uuid,
  "stage_entered_at" timestamp with time zone,
  "state"            text                     NOT NULL DEFAULT 'active'::text,
  "rejection_reason" text,
  "hired_at"         timestamp with time zone,
  "rank"             text                     COLLATE pg_catalog."C" NOT NULL DEFAULT 'V'::text,
  "created_at"       timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"       timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "applications_job_id_candidate_type_candidate_id_key" UNIQUE (job_id, candidate_type, candidate_id),
  CONSTRAINT "applications_pkey" PRIMARY KEY (id),
  CONSTRAINT "applications_state_check" CHECK ((state = ANY (ARRAY['active'::text, 'hired'::text, 'rejected'::text, 'withdrawn'::text])))
);

ALTER TABLE "better_supabase"."applications"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."approval_decisions" (
  "id"          uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "request_id"  uuid                     NOT NULL,
  "tenant_id"   uuid                     NOT NULL,
  "step"        integer                  NOT NULL,
  "approver"    uuid,
  "decision"    text                     NOT NULL,
  "delegate_to" uuid,
  "comment"     text,
  "created_at"  timestamp with time zone NOT NULL DEFAULT clock_timestamp(),
  CONSTRAINT "approval_decisions_check" CHECK (((decision = 'delegated'::text) = (delegate_to IS NOT NULL))),
  CONSTRAINT "approval_decisions_comment_check" CHECK (((comment IS NULL) OR (length(comment) <= 2000))),
  CONSTRAINT "approval_decisions_decision_check" CHECK ((decision = ANY (ARRAY['approved'::text, 'rejected'::text, 'delegated'::text]))),
  CONSTRAINT "approval_decisions_pkey" PRIMARY KEY (id),
  CONSTRAINT "approval_decisions_request_id_step_approver_key" UNIQUE (request_id, step, approver)
);

ALTER TABLE "better_supabase"."approval_decisions"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."approval_requests" (
  "id"           uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"    uuid                     NOT NULL,
  "subject_type" text                     NOT NULL,
  "subject_id"   text                     NOT NULL,
  "action"       text                     NOT NULL,
  "policy"       jsonb                    NOT NULL,
  "step"         integer                  NOT NULL DEFAULT 0,
  "status"       text                     NOT NULL DEFAULT 'pending'::text,
  "requested_by" uuid,
  "reason"       text,
  "payload"      jsonb                    NOT NULL DEFAULT '{}'::jsonb,
  "expires_at"   timestamp with time zone,
  "reminded_at"  timestamp with time zone,
  "decided_at"   timestamp with time zone,
  "created_at"   timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "approval_requests_pkey" PRIMARY KEY (id),
  CONSTRAINT "approval_requests_reason_check" CHECK (((reason IS NULL) OR (length(reason) <= 2000))),
  CONSTRAINT "approval_requests_status_check" CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text, 'cancelled'::text, 'expired'::text]))),
  CONSTRAINT "approval_requests_step_check" CHECK ((step >= 0))
);

ALTER TABLE "better_supabase"."approval_requests"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."attachments" (
  "id"              uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "organization_id" uuid                     NOT NULL,
  "subject_type"    text,
  "subject_id"      text,
  "bucket"          text                     NOT NULL DEFAULT 'attachments'::text,
  "name"            text                     NOT NULL,
  "mime_type"       text                     NOT NULL,
  "size"            bigint                   NOT NULL,
  "status"          text                     NOT NULL DEFAULT 'pending'::text,
  "scan_detail"     text,
  "created_at"      timestamp with time zone NOT NULL DEFAULT clock_timestamp(),
  "uploaded_at"     timestamp with time zone,
  "scanned_at"      timestamp with time zone,
  "metadata"        jsonb                    NOT NULL DEFAULT '{}'::jsonb,
  CONSTRAINT "attachments_check" CHECK (((subject_type IS NULL) = (subject_id IS NULL))),
  CONSTRAINT "attachments_metadata_check" CHECK ((jsonb_typeof(metadata) = 'object'::text)),
  CONSTRAINT "attachments_mime_type_check" CHECK ((mime_type ~ '^[a-z0-9.+-]+/[a-z0-9.+-]+$'::text)),
  CONSTRAINT "attachments_name_check" CHECK (((length(name) >= 1) AND (length(name) <= 255))),
  CONSTRAINT "attachments_pkey" PRIMARY KEY (id),
  CONSTRAINT "attachments_status_check" CHECK ((status = ANY (ARRAY['pending'::text, 'clean'::text, 'infected'::text, 'failed'::text]))),
  CONSTRAINT "attachments_subject_id_check" CHECK (((length(subject_id) >= 1) AND (length(subject_id) <= 200))),
  CONSTRAINT "attachments_subject_type_check" CHECK ((subject_type ~ '^[a-z][a-z0-9_]{0,62}$'::text)),
  CONSTRAINT "bs_attachments_size" CHECK (((size >= 0) AND (size <= 52428800))),
  "uploaded_by"     uuid                     DEFAULT auth.uid()
);

ALTER TABLE "better_supabase"."attachments"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."booking_availability" (
  "id"          uuid                   NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"   uuid                   NOT NULL,
  "resource_id" uuid                   NOT NULL,
  "weekday"     smallint               NOT NULL,
  "starts_at"   time without time zone NOT NULL,
  "ends_at"     time without time zone NOT NULL,
  CONSTRAINT "booking_availability_check" CHECK ((ends_at > starts_at)),
  CONSTRAINT "booking_availability_pkey" PRIMARY KEY (id),
  CONSTRAINT "booking_availability_weekday_check" CHECK (((weekday >= 1) AND (weekday <= 7)))
);

ALTER TABLE "better_supabase"."booking_availability"
  ENABLE ROW LEVEL SECURITY;

