  CONSTRAINT "booking_resources_capacity_check" CHECK (((capacity >= 1) AND (capacity <= 1000))),
  CONSTRAINT "booking_resources_name_check" CHECK (((length(name) >= 1) AND (length(name) <= 120))),
  CONSTRAINT "booking_resources_pkey" PRIMARY KEY (id)
