ALTER TABLE "better_supabase"."booking_resources"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."booking_services" (
  "id"               uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"        uuid                     NOT NULL,
  "name"             text                     NOT NULL,
  "duration"         interval                 NOT NULL,
  "buffer_before"    interval                 NOT NULL DEFAULT '00:00:00'::interval,
  "buffer_after"     interval                 NOT NULL DEFAULT '00:00:00'::interval,
  "resource_kinds"   text[]                   NOT NULL DEFAULT '{}'::text[],
  "step"             interval,
  "min_notice"       interval                 NOT NULL DEFAULT '00:00:00'::interval,
  "hold_for"         interval                 NOT NULL DEFAULT '00:10:00'::interval,
  "reminder_offsets" integer[]                NOT NULL DEFAULT '{1440}'::integer[],
  "active"           boolean                  NOT NULL DEFAULT true,
  "created_at"       timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "booking_services_buffer_after_check" CHECK ((buffer_after >= '00:00:00'::interval)),
  CONSTRAINT "booking_services_buffer_before_check" CHECK ((buffer_before >= '00:00:00'::interval)),
  CONSTRAINT "booking_services_duration_check" CHECK ((duration > '00:00:00'::interval)),
  CONSTRAINT "booking_services_hold_for_check" CHECK ((hold_for > '00:00:00'::interval)),
  CONSTRAINT "booking_services_name_check" CHECK (((length(name) >= 1) AND (length(name) <= 120))),
  CONSTRAINT "booking_services_pkey" PRIMARY KEY (id),
  CONSTRAINT "booking_services_step_check" CHECK ((step > '00:00:00'::interval))
);

ALTER TABLE "better_supabase"."booking_services"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."bookings" (
  "id"                uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"         uuid                     NOT NULL,
  "resource_id"       uuid                     NOT NULL,
  "service_id"        uuid                     NOT NULL,
  "seat"              integer                  NOT NULL DEFAULT 1,
  "during"            tstzrange                NOT NULL,
  "blocked"           tstzrange                NOT NULL,
  "status"            text                     NOT NULL DEFAULT 'hold'::text,
  "hold_expires_at"   timestamp with time zone,
  "customer_name"     text,
  "customer_email"    text,
  "customer_user_id"  uuid,
  "notes"             text,
  "access_hash"       text,
  "calendar_event_id" uuid,
  "created_by"        uuid,
  "created_at"        timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"        timestamp with time zone NOT NULL DEFAULT now(),
  "cancelled_at"      timestamp with time zone,
  "cancel_reason"     text,
  CONSTRAINT "bookings_access_hash_key" UNIQUE (access_hash),
  CONSTRAINT "bookings_check1" CHECK (((status = 'hold'::text) = (hold_expires_at IS NOT NULL))),
  CONSTRAINT "bookings_check" CHECK ((blocked @> during)),
  CONSTRAINT "bookings_during_check" CHECK ((NOT isempty(during))),
  CONSTRAINT "bookings_pkey" PRIMARY KEY (id),
  CONSTRAINT "bookings_seat_check" CHECK ((seat >= 1)),
  CONSTRAINT "bookings_status_check" CHECK ((status = ANY (ARRAY['hold'::text, 'confirmed'::text, 'cancelled'::text])))
);

ALTER TABLE "better_supabase"."bookings"
  ENABLE ROW LEVEL SECURITY;

