  CONSTRAINT "deals_pkey" PRIMARY KEY (id),
  CONSTRAINT "deals_probability_check" CHECK (((probability >= 0) AND (probability <= 100))),
  CONSTRAINT "deals_seats_check" CHECK ((seats >= 0)),
  CONSTRAINT "deals_tenant_id_number_key" UNIQUE (tenant_id, number),
  CONSTRAINT "deals_value_period_check" CHECK ((value_period = ANY (ARRAY['one_time'::text, 'monthly'::text, 'annual'::text])))
);

