  CONSTRAINT "promotions_amount_check" CHECK ((amount > 0)),
  CONSTRAINT "promotions_check1" CHECK (((kind = 'fixed'::text) = (amount IS NOT NULL))),
  CONSTRAINT "promotions_check2" CHECK ((((amount IS NULL) AND (min_subtotal IS NULL)) OR (currency IS NOT NULL))),
  CONSTRAINT "promotions_check3" CHECK (((ends_at IS NULL) OR (starts_at IS NULL) OR (ends_at > starts_at))),
  CONSTRAINT "promotions_check" CHECK (((kind = 'percentage'::text) = (percent IS NOT NULL))),
  CONSTRAINT "promotions_currency_check" CHECK ((currency ~ '^[A-Z]{3}$'::text)),
  CONSTRAINT "promotions_description_check" CHECK ((length(description) <= 2000)),
