  CONSTRAINT "promotions_per_customer_limit_check" CHECK ((per_customer_limit > 0)),
  CONSTRAINT "promotions_percent_check" CHECK (((percent > (0)::numeric) AND (percent <= (100)::numeric))),
  CONSTRAINT "promotions_pkey" PRIMARY KEY (id),
  CONSTRAINT "promotions_redemptions_check" CHECK ((redemptions >= 0)),
  CONSTRAINT "promotions_scope_check" CHECK ((scope = ANY (ARRAY['order'::text, 'products'::text, 'categories'::text, 'collections'::text]))),
