  CONSTRAINT "versions_check" CHECK (((content IS NOT NULL) OR (storage_path IS NOT NULL))),
  CONSTRAINT "versions_label_check" CHECK (((length(label) >= 1) AND (length(label) <= 120))),
  CONSTRAINT "versions_number_check" CHECK ((number > 0)),
  CONSTRAINT "versions_pkey" PRIMARY KEY (id),
  CONSTRAINT "versions_source_check" CHECK ((source = ANY (ARRAY['manual'::text, 'auto'::text, 'restore'::text]))),
  CONSTRAINT "versions_subject_type_subject_id_number_key" UNIQUE (subject_type, subject_id, number)
);

ALTER TABLE "better_supabase"."versions"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."waitlist_entries" (
  "id"         uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "email"      text                     NOT NULL,
  "status"     text                     NOT NULL DEFAULT 'waiting'::text,
  "position"   bigint                   GENERATED ALWAYS AS IDENTITY NOT NULL,
  "referrer"   text,
  "metadata"   jsonb                    NOT NULL DEFAULT '{}'::jsonb,
  "user_id"    uuid,
  "decided_by" uuid,
  "decided_at" timestamp with time zone,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "waitlist_entries_email_check" CHECK (((email = lower(email)) AND (email ~ '^[^@[:space:]]+@[^@[:space:]]+$'::text))),
  CONSTRAINT "waitlist_entries_email_key" UNIQUE (email),
  CONSTRAINT "waitlist_entries_metadata_check" CHECK (((jsonb_typeof(metadata) = 'object'::text) AND (pg_column_size(metadata) <= 4096))),
  CONSTRAINT "waitlist_entries_pkey" PRIMARY KEY (id),
  CONSTRAINT "waitlist_entries_referrer_check" CHECK ((length(referrer) <= 200)),
  CONSTRAINT "waitlist_entries_status_check" CHECK ((status = ANY (ARRAY['waiting'::text, 'approved'::text, 'rejected'::text, 'joined'::text])))
);

ALTER TABLE "better_supabase"."waitlist_entries"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."webhook_deliveries" (
  "id"              uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "organization_id" uuid,
  "endpoint_id"     uuid                     NOT NULL,
  "event_id"        text,
  "run_id"          text,
  "event_type"      text                     NOT NULL,
  "subject"         text,
  "payload"         jsonb                    NOT NULL DEFAULT '{}'::jsonb,
  "status"          text                     NOT NULL DEFAULT 'pending'::text,
  "attempt"         integer                  NOT NULL DEFAULT 0,
  "available_at"    timestamp with time zone NOT NULL DEFAULT now(),
  "leased_until"    timestamp with time zone,
  "response_status" integer,
  "response_body"   text,
  "duration_ms"     integer,
  "last_error"      text,
  "processed_at"    timestamp with time zone,
  "created_at"      timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"      timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "webhook_deliveries_attempt_check" CHECK ((attempt >= 0)),
  CONSTRAINT "webhook_deliveries_pkey" PRIMARY KEY (id),
  CONSTRAINT "webhook_deliveries_status_check"
    CHECK ((status = ANY (ARRAY['pending'::text, 'delivering'::text, 'succeeded'::text, 'retrying'::text, 'dead'::text, 'canceled'::text])))
);

ALTER TABLE "better_supabase"."webhook_deliveries"
  ENABLE ROW LEVEL SECURITY;

