);

ALTER TABLE "better_supabase"."webhook_endpoint_secrets"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."webhook_endpoints" (
  "id"              uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "organization_id" uuid                     NOT NULL,
  "name"            text                     NOT NULL,
  "url"             text                     NOT NULL,
  "enabled"         boolean                  NOT NULL DEFAULT true,
  "event_types"     text[]                   NOT NULL DEFAULT '{}'::text[],
  "permissions"     text[],
  "batch"           boolean                  NOT NULL DEFAULT false,
  "signing"         text                     NOT NULL DEFAULT 'v1'::text,
  "format"          text                     NOT NULL DEFAULT 'cloudevents'::text,
  "credential_ref"  jsonb,
  "failing_since"   timestamp with time zone,
  "disabled_at"     timestamp with time zone,
  "disabled_reason" text,
  "created_at"      timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"      timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "webhook_endpoints_credential_ref_check"
    CHECK (((credential_ref IS NULL) OR ((jsonb_typeof(credential_ref) = 'object'::text) AND (credential_ref ? 'provider'::text)))),
  CONSTRAINT "webhook_endpoints_format_check" CHECK ((format ~ '^[a-z][a-z0-9-]{0,39}$'::text)),
  CONSTRAINT "webhook_endpoints_name_check" CHECK ((length(TRIM(BOTH FROM name)) > 0)),
  CONSTRAINT "webhook_endpoints_pkey" PRIMARY KEY (id),
  CONSTRAINT "webhook_endpoints_signing_check" CHECK ((signing = ANY (ARRAY['v1'::text, 'v1a'::text]))),
  CONSTRAINT "webhook_endpoints_url_check" CHECK ((url ~* '^https://'::text)),
  "created_by"      uuid                     DEFAULT auth.uid()
);

ALTER TABLE "better_supabase"."webhook_endpoints"
  ENABLE ROW LEVEL SECURITY;

