CREATE TABLE "better_supabase"."work_items" (
  "id"               uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"        uuid                     NOT NULL,
  "number"           bigint                   NOT NULL,
  "identifier"       text                     NOT NULL,
  "title"            text                     NOT NULL,
  "body"             text,
  "parent_id"        uuid,
  "team_id"          uuid,
  "project_id"       uuid,
  "iteration_id"     uuid,
  "priority"         smallint                 NOT NULL DEFAULT 0,
  "estimate"         numeric(10,2),
  "progress"         smallint,
  "start_at"         timestamp with time zone,
  "end_at"           timestamp with time zone,
  "due_at"           timestamp with time zone,
  "pipeline_id"      uuid,
  "stage_id"         uuid,
  "stage_entered_at" timestamp with time zone,
  "state"            text                     NOT NULL DEFAULT 'backlog'::text,
  "close_reason"     text,
  "closed_at"        timestamp with time zone,
  "locked"           boolean                  NOT NULL DEFAULT false,
  "rank"             text                     COLLATE pg_catalog."C" NOT NULL DEFAULT 'V'::text,
  "archived_at"      timestamp with time zone,
  "created_by"       uuid,
  "created_at"       timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"       timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "work_items_check" CHECK (((end_at IS NULL) OR (start_at IS NULL) OR (end_at >= start_at))),
  CONSTRAINT "work_items_close_reason_check" CHECK ((close_reason = ANY (ARRAY['completed'::text, 'not_planned'::text, 'duplicate'::text]))),
  CONSTRAINT "work_items_estimate_check" CHECK ((estimate >= (0)::numeric)),
  CONSTRAINT "work_items_pkey" PRIMARY KEY (id),
  CONSTRAINT "work_items_priority_check" CHECK (((priority >= 0) AND (priority <= 4))),
  CONSTRAINT "work_items_progress_check" CHECK (((progress >= 0) AND (progress <= 100))),
  CONSTRAINT "work_items_state_check" CHECK ((state = ANY (ARRAY['triage'::text, 'backlog'::text, 'unstarted'::text, 'started'::text, 'completed'::text, 'canceled'::text]))),
  CONSTRAINT "work_items_tenant_id_number_key" UNIQUE (tenant_id, number),
  CONSTRAINT "work_items_title_check" CHECK (((length(title) >= 1) AND (length(title) <= 500)))
);

ALTER TABLE "better_supabase"."work_items"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."work_projects" (
  "id"            uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"     uuid                     NOT NULL,
  "key"           text                     NOT NULL,
  "name"          text                     NOT NULL,
  "owner_user_id" uuid,
  "status"        text                     NOT NULL DEFAULT 'planned'::text,
  "start_on"      date,
  "target_on"     date,
  "archived_at"   timestamp with time zone,
  "created_at"    timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"    timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "work_projects_check" CHECK (((target_on IS NULL) OR (start_on IS NULL) OR (target_on >= start_on))),
  CONSTRAINT "work_projects_key_check" CHECK ((key ~ '^[A-Z][A-Z0-9]{0,9}$'::text)),
  CONSTRAINT "work_projects_name_check" CHECK (((length(name) >= 1) AND (length(name) <= 200))),
  CONSTRAINT "work_projects_pkey" PRIMARY KEY (id),
  CONSTRAINT "work_projects_status_check" CHECK ((status = ANY (ARRAY['planned'::text, 'active'::text, 'paused'::text, 'completed'::text, 'canceled'::text]))),
  CONSTRAINT "work_projects_tenant_id_key_key" UNIQUE (tenant_id, key)
);

ALTER TABLE "better_supabase"."work_projects"
  ENABLE ROW LEVEL SECURITY;

