    where r."id" = new."id";
  end if;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.bs_pipeline_work_item()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
