ALTER TABLE "better_supabase"."attachments"
  ADD CONSTRAINT "attachments_uploaded_by_fkey" FOREIGN KEY (uploaded_by) REFERENCES auth.users(id) ON DELETE SET NULL;

CREATE INDEX attachments_uploaded_by_idx ON better_supabase.attachments USING btree (uploaded_by);

CREATE POLICY "attachments_delete" ON "better_supabase"."attachments"
  FOR DELETE
  TO "authenticated"
  USING
    ((((uploaded_by = ( SELECT auth.uid() AS uid)) OR (organization_id IN ( SELECT better_supabase.tenant_ids_with('attachments.manage'::text) AS tenant_ids_with))) AND ( SELECT
    better_supabase.actor_may_write() AS actor_may_write)));

CREATE POLICY "attachments_insert" ON "better_supabase"."attachments"
  FOR INSERT
  TO "authenticated"
  WITH
    CHECK
    (((uploaded_by = ( SELECT auth.uid() AS uid)) AND COALESCE(better_supabase.can('tenant'::text, organization_id, 'attachments.upload'::text), false) AND
    better_supabase.attachment_subject_readable(subject_type, subject_id, organization_id) AND ( SELECT better_supabase.actor_may_write() AS actor_may_write)));

ALTER TABLE "better_supabase"."data_exports"
  ADD CONSTRAINT "data_exports_requested_by_fkey" FOREIGN KEY (requested_by) REFERENCES auth.users(id) ON DELETE SET NULL;

CREATE INDEX data_exports_requested_by_idx ON better_supabase.data_exports USING btree (requested_by);

CREATE POLICY "data_exports_read" ON "better_supabase"."data_exports"
  FOR SELECT
  TO "authenticated"
  USING (((requested_by = ( SELECT auth.uid() AS uid)) OR (organization_id IN ( SELECT better_supabase.tenant_ids_with('organization.export'::text) AS tenant_ids_with))));

